use std::collections::HashMap;

use petstore::{ConfigurationBuilder, ConfigurationError, ServerConfiguration, ServerVariable};

fn server_with_vars() -> ServerConfiguration {
    let mut variables = HashMap::new();
    variables.insert(
        "env".to_string(),
        ServerVariable::new(
            "api".to_string(),
            "the environment".to_string(),
            vec!["api".to_string(), "staging".to_string()],
        ),
    );
    variables.insert(
        "version".to_string(),
        ServerVariable::new(
            "v3".to_string(),
            String::new(),
            vec!["v2".to_string(), "v3".to_string()],
        ),
    );
    ServerConfiguration::new(
        "https://{env}.example.com/api/{version}".to_string(),
        "Test server".to_string(),
        variables,
    )
}

