/// F1124: the third global server keeps its hostile text unchanged: the
/// description, the variable default and description, and the enum values.
#[test]
fn test_bhv_servers_013_the_third_global_server_keeps_its_hostile_text_unchanged() {
    let server = petstore::servers::server_2();

    assert_eq!("https://{tenant}.example.com/api", server.url_template());
    assert_eq!("Bob's \"sandbox\" & co: $5 #{x} a*/b", server.description());
    let tenant = server
        .variables()
        .get("tenant")
        .expect("the tenant variable");
    assert_eq!("o'neil", tenant.default_value());
    assert_eq!("Tenant's \"id\"", tenant.description());
    assert_eq!(
        vec!["o'neil".to_string(), "a&b".to_string()],
        tenant.enum_values()
    );
    assert_eq!(
        "https://o'neil.example.com/api",
        server.url(&HashMap::new()).unwrap()
    );
    let mut overrides = HashMap::new();
    overrides.insert("tenant".to_string(), "a&b".to_string());
    assert_eq!(
        "https://a&b.example.com/api",
        server.url(&overrides).unwrap()
    );
}

